package main

import "base:intrinsics"
import "core:io"
import "core:strings"

// Evaluation uses an explicit operator stack (shunting-yard) rather than
// recursive descent, so deeply nested input cannot overflow the call stack.

@(private = "file")
Op :: enum u8 {
	Add,
	Sub,
	Mul,
	Div,
	Mod,
	Neg,
	Paren,
}

@(private = "file")
precedence :: proc(op: Op) -> int {
	switch op {
	case .Add, .Sub:
		return 1
	case .Mul, .Div, .Mod:
		return 2
	case .Neg:
		return 3
	case .Paren:
		return 0
	}
	return 0
}

@(private = "file")
Calc_Error :: enum u8 {
	None,
	Syntax,
	Div_By_Zero,
	Overflow,
}

@(private = "file")
Evaluator :: struct {
	values: [dynamic]i64,
	ops:    [dynamic]Op,
}

// Pops one operator and applies it to the value stack.
@(private = "file")
reduce :: proc(e: ^Evaluator) -> Calc_Error {
	op := pop(&e.ops)
	if op == .Neg {
		x := &e.values[len(e.values) - 1]
		if x^ == min(i64) {
			return .Overflow
		}
		x^ = -x^
		return .None
	}

	b := pop(&e.values)
	a := &e.values[len(e.values) - 1]
	overflow: bool
	#partial switch op {
	case .Add:
		a^, overflow = intrinsics.overflow_add(a^, b)
	case .Sub:
		a^, overflow = intrinsics.overflow_sub(a^, b)
	case .Mul:
		a^, overflow = intrinsics.overflow_mul(a^, b)
	case .Div:
		if b == 0 {
			return .Div_By_Zero
		}
		if a^ == min(i64) && b == -1 {
			return .Overflow
		}
		a^ /= b
	case .Mod:
		if b == 0 {
			return .Div_By_Zero
		}
		a^ = 0 if b == -1 else a^ % b
	}
	return .Overflow if overflow else .None
}

@(private = "file")
is_blank :: #force_inline proc(c: byte) -> bool {
	return c == ' ' || c == '\t'
}

// Evaluates one expression line.
@(private = "file")
evaluate :: proc(e: ^Evaluator, line: string) -> (result: i64, err: Calc_Error) {
	clear(&e.values)
	clear(&e.ops)

	expect_operand := true
	i, n := 0, len(line)
	for i < n {
		c := line[i]
		if is_blank(c) {
			i += 1
			continue
		}

		if expect_operand {
			switch c {
			case '0' ..= '9':
				v: i64
				for i < n && line[i] >= '0' && line[i] <= '9' {
					overflow_m, overflow_a: bool
					v, overflow_m = intrinsics.overflow_mul(v, 10)
					v, overflow_a = intrinsics.overflow_add(v, i64(line[i] - '0'))
					if overflow_m || overflow_a {
						return 0, .Overflow
					}
					i += 1
				}
				append(&e.values, v)
				expect_operand = false
				continue
			case '(':
				append(&e.ops, Op.Paren)
			case '-':
				append(&e.ops, Op.Neg)
			case:
				return 0, .Syntax
			}
			i += 1
			continue
		}

		op: Op
		switch c {
		case '+':
			op = .Add
		case '-':
			op = .Sub
		case '*':
			op = .Mul
		case '/':
			op = .Div
		case '%':
			op = .Mod
		case ')':
			for {
				if len(e.ops) == 0 {
					return 0, .Syntax
				}
				if e.ops[len(e.ops) - 1] == .Paren {
					pop(&e.ops)
					break
				}
				reduce(e) or_return
			}
			i += 1
			continue
		case:
			return 0, .Syntax
		}

		// All binary operators are left-associative.
		p := precedence(op)
		for len(e.ops) > 0 && precedence(e.ops[len(e.ops) - 1]) >= p {
			reduce(e) or_return
		}
		append(&e.ops, op)
		expect_operand = true
		i += 1
	}

	if expect_operand {
		return 0, .Syntax
	}
	for len(e.ops) > 0 {
		if e.ops[len(e.ops) - 1] == .Paren {
			return 0, .Syntax
		}
		reduce(e) or_return
	}
	return e.values[0], .None
}

// Evaluates each input line as a 64-bit integer expression, printing its
// value or `error`. Blank lines print nothing.
calc :: proc(input: []byte, w: io.Writer) {
	e: Evaluator
	defer {
		delete(e.values)
		delete(e.ops)
	}

	text := string(input)
	for line in strings.split_lines_iterator(&text) {
		if len(strings.trim(line, " \t")) == 0 {
			continue
		}
		if value, err := evaluate(&e, line); err == .None {
			write_int(w, value)
			io.write_byte(w, '\n')
		} else {
			write_line(w, "error")
		}
	}
}

package main

import "core:io"
import "core:strconv"
import "core:strings"

NIL_NODE :: -1

@(private = "file")
Node :: struct {
	key:   string,
	value: string,
	prev:  i32,
	next:  i32,
}

// LRU cache: a hash map from key to node index plus an intrusive doubly linked
// list over a node pool, most recently used at `head`. All operations are O(1)
// expected. Keys and values borrow from the input buffer.
@(private = "file")
Cache :: struct {
	capacity: int,
	index:    map[string]i32,
	nodes:    [dynamic]Node,
	free:     [dynamic]i32,
	head:     i32,
	tail:     i32,
}

@(private = "file")
cache_init :: proc(c: ^Cache, capacity: int) {
	c.capacity = capacity
	reserve_count := min(capacity + 1, 1 << 16)
	c.index = make(map[string]i32, reserve_count)
	c.nodes = make([dynamic]Node, 0, reserve_count)
	c.free = make([dynamic]i32)
	c.head = NIL_NODE
	c.tail = NIL_NODE
}

@(private = "file")
cache_destroy :: proc(c: ^Cache) {
	delete(c.index)
	delete(c.nodes)
	delete(c.free)
}

@(private = "file")
unlink :: proc(c: ^Cache, i: i32) {
	n := &c.nodes[i]
	if n.prev != NIL_NODE {
		c.nodes[n.prev].next = n.next
	} else {
		c.head = n.next
	}
	if n.next != NIL_NODE {
		c.nodes[n.next].prev = n.prev
	} else {
		c.tail = n.prev
	}
}

@(private = "file")
push_front :: proc(c: ^Cache, i: i32) {
	n := &c.nodes[i]
	n.prev = NIL_NODE
	n.next = c.head
	if c.head != NIL_NODE {
		c.nodes[c.head].prev = i
	} else {
		c.tail = i
	}
	c.head = i
}

@(private = "file")
remove_node :: proc(c: ^Cache, i: i32) {
	unlink(c, i)
	delete_key(&c.index, c.nodes[i].key)
	append(&c.free, i)
}

@(private = "file")
cache_set :: proc(c: ^Cache, key, value: string) {
	if i, found := c.index[key]; found {
		c.nodes[i].value = value
		if c.head != i {
			unlink(c, i)
			push_front(c, i)
		}
		return
	}

	i: i32
	if len(c.free) > 0 {
		i = pop(&c.free)
		c.nodes[i] = {key = key, value = value}
	} else {
		i = i32(len(c.nodes))
		append(&c.nodes, Node{key = key, value = value})
	}
	c.index[key] = i
	push_front(c, i)

	if len(c.index) > c.capacity {
		remove_node(c, c.tail)
	}
}

@(private = "file")
cache_get :: proc(c: ^Cache, key: string) -> (value: string, found: bool) {
	i := c.index[key] or_return
	if c.head != i {
		unlink(c, i)
		push_front(c, i)
	}
	return c.nodes[i].value, true
}

@(private = "file")
cache_del :: proc(c: ^Cache, key: string) -> bool {
	i := c.index[key] or_return
	remove_node(c, i)
	return true
}

// Runs the LRU cache simulation: the first line is the capacity, each later
// line one command.
lru :: proc(input: []byte, w: io.Writer) {
	text := string(input)

	first, _ := strings.split_lines_iterator(&text)
	capacity, ok := strconv.parse_int(strings.trim_space(first), 10)
	if !ok || capacity < 1 {
		return
	}

	cache: Cache
	cache_init(&cache, capacity)
	defer cache_destroy(&cache)

	for line in strings.split_lines_iterator(&text) {
		rest := strings.trim_right(line, "\r")
		cmd, _ := strings.split_iterator(&rest, " ")
		switch cmd {
		case "SET":
			key, _ := strings.split_iterator(&rest, " ")
			value, _ := strings.split_iterator(&rest, " ")
			cache_set(&cache, key, value)
		case "GET":
			key, _ := strings.split_iterator(&rest, " ")
			if value, found := cache_get(&cache, key); found {
				write_line(w, value)
			} else {
				write_line(w, "NULL")
			}
		case "DEL":
			key, _ := strings.split_iterator(&rest, " ")
			write_line(w, "1" if cache_del(&cache, key) else "0")
		case "SIZE":
			write_int(w, i64(len(cache.index)))
			io.write_byte(w, '\n')
		}
	}
}

// suite: a command-line program with three independent subcommands
// (wordfreq, lru, calc). Each reads standard input and writes standard output.
package main

import "core:bufio"
import "core:fmt"
import "core:io"
import "core:os"
import "core:strconv"

USAGE :: "usage: app <wordfreq | lru | calc>"

main :: proc() {
	if len(os.args) < 2 {
		fmt.eprintln(USAGE)
		os.exit(2)
	}

	input, ok := read_all_stdin()
	if !ok {
		fmt.eprintln("error: failed to read standard input")
		os.exit(1)
	}

	out: bufio.Writer
	bufio.writer_init(&out, os.to_stream(os.stdout), 1 << 16)
	defer bufio.writer_destroy(&out)
	w := bufio.writer_to_writer(&out)

	switch os.args[1] {
	case "wordfreq":
		wordfreq(input, w)
	case "lru":
		lru(input, w)
	case "calc":
		calc(input, w)
	case:
		fmt.eprintln(USAGE)
		os.exit(2)
	}

	if bufio.writer_flush(&out) != nil {
		os.exit(1)
	}
}

// Reads all of standard input into a single buffer. Works for pipes as well as
// regular files, growing geometrically so large inputs stay linear-time.
read_all_stdin :: proc(allocator := context.allocator) -> (data: []byte, ok: bool) {
	buf := make([dynamic]byte, 1 << 20, allocator)
	total := 0
	for {
		if len(buf) - total < 1 << 16 {
			non_zero_resize(&buf, 2 * len(buf))
		}
		n, err := os.read(os.stdin, buf[total:])
		total += n
		if err == .EOF || (err == nil && n == 0) {
			break
		}
		if err != nil {
			delete(buf)
			return nil, false
		}
	}
	return buf[:total], true
}

write_int :: proc(w: io.Writer, v: i64) {
	digits: [32]byte
	io.write_string(w, strconv.write_int(digits[:], v, 10))
}

write_line :: proc(w: io.Writer, s: string) {
	io.write_string(w, s)
	io.write_byte(w, '\n')
}

package main

import "core:io"
import "core:slice"

TOP_WORDS :: 10

FNV_OFFSET :: u64(0xcbf29ce484222325)
FNV_PRIME :: u64(0x100000001b3)

@(private = "file")
Word_Entry :: struct {
	hash:  u64,
	word:  string, // slice of the (lowercased) input buffer; empty means unused slot
	count: int,
}

// Open-addressing hash table from word to count. Keys borrow from the input
// buffer, so counting allocates nothing per word.
@(private = "file")
Word_Table :: struct {
	slots: []Word_Entry,
	used:  int,
}

@(private = "file")
table_init :: proc(t: ^Word_Table, capacity: int) {
	t.slots = make([]Word_Entry, capacity)
	t.used = 0
}

@(private = "file")
table_destroy :: proc(t: ^Word_Table) {
	delete(t.slots)
}

@(private = "file")
table_add :: proc(t: ^Word_Table, word: string, hash: u64) {
	if 2 * (t.used + 1) > len(t.slots) {
		table_grow(t)
	}
	mask := u64(len(t.slots) - 1)
	i := hash & mask
	for {
		e := &t.slots[i]
		if len(e.word) == 0 {
			e^ = {hash, word, 1}
			t.used += 1
			return
		}
		if e.hash == hash && e.word == word {
			e.count += 1
			return
		}
		i = (i + 1) & mask
	}
}

@(private = "file")
table_grow :: proc(t: ^Word_Table) {
	old := t.slots
	t.slots = make([]Word_Entry, 2 * len(old))
	mask := u64(len(t.slots) - 1)
	for e in old {
		if len(e.word) == 0 {
			continue
		}
		i := e.hash & mask
		for len(t.slots[i].word) != 0 {
			i = (i + 1) & mask
		}
		t.slots[i] = e
	}
	delete(old)
}

// Prints the TOP_WORDS most frequent words: count descending, then word ascending.
// Lowercases `input` in place.
wordfreq :: proc(input: []byte, w: io.Writer) {
	table: Word_Table
	table_init(&table, 1 << 12)
	defer table_destroy(&table)

	i, n := 0, len(input)
	for i < n {
		c := input[i]
		if !is_ascii_letter(c) {
			i += 1
			continue
		}
		start := i
		hash := FNV_OFFSET
		for i < n {
			c = input[i]
			if !is_ascii_letter(c) {
				break
			}
			c |= 0x20 // ASCII letters: setting bit 5 lowercases
			input[i] = c
			hash = (hash ~ u64(c)) * FNV_PRIME
			i += 1
		}
		table_add(&table, string(input[start:i]), hash)
	}

	entries := make([dynamic]Word_Entry, 0, table.used)
	defer delete(entries)
	for e in table.slots {
		if len(e.word) != 0 {
			append(&entries, e)
		}
	}

	ranks_before :: proc(a, b: Word_Entry) -> bool {
		if a.count != b.count {
			return a.count > b.count
		}
		return a.word < b.word
	}
	slice.sort_by(entries[:], ranks_before)

	for e in entries[:min(len(entries), TOP_WORDS)] {
		write_int(w, i64(e.count))
		io.write_byte(w, ' ')
		write_line(w, e.word)
	}
}

@(private = "file")
is_ascii_letter :: #force_inline proc(c: byte) -> bool {
	return (c | 0x20) - 'a' < 26
}
